package com.bank.transfer.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class TransferService {

    private final AccountRepository accountRepo;
    private final OutboxRepository outboxRepo;

    // ONE local transaction: ledger change AND outbox row commit together or not at all.
    @Transactional
    public void transfer(String from, String to, BigDecimal amount) {
        accountRepo.debit(from, amount);
        accountRepo.credit(to, amount);
        String eventId = UUID.randomUUID().toString();
        outboxRepo.insert(new OutboxEvent(eventId, from, "TransferCompleted",
                "{\"from\":\"" + from + "\",\"to\":\"" + to + "\",\"amount\":" + amount + "}"));
        log.info("Transfer {} -> {} amount {} persisted with outbox event {}",
                from, to, amount, eventId);
        // Deliberately NO Kafka call here. The relay publishes from the outbox.
    }
}
