package com.bank.transfer.outbox;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import java.util.List;

@Component
@RequiredArgsConstructor
@Slf4j
public class OutboxRelay {

    private final OutboxRepository outboxRepo;
    private final KafkaTemplate<String, String> kafka;

    // Polling publisher: at-least-once. If we crash after send() before markPublished,
    // the row is republished on restart; consumers dedupe by event id.
    @Scheduled(fixedDelayString = "${outbox.relay.poll-interval-ms}")
    public void publishPending() {
        List<OutboxEvent> pending = outboxRepo.findUnpublished(200);
        for (OutboxEvent e : pending) {
            // key = aggregateId preserves per-account ordering; header carries event id
            kafka.send("transfer.events", e.getAggregateId(), e.getPayload())
                 .whenComplete((res, ex) -> {
                     if (ex == null) outboxRepo.markPublished(e.getId());
                     else log.warn("Relay publish failed for {}, will retry", e.getId(), ex);
                 });
        }
    }
}
