package com.bank.transfer.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OutboxDemo {

    private static final Logger log = Logger.getLogger(OutboxDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Naive dual-write: DB commit then Kafka publish, crash in between ===");
        Database db1 = new Database();
        KafkaBroker broker1 = new KafkaBroker();
        try {
            db1.begin();
            db1.applyTransfer("SAV2001", "CUR3001", new BigDecimal("50000"));
            db1.commit();                 // ledger committed
            throw new RuntimeException("CRASH before Kafka publish");
            // broker1.publish(...) never runs
        } catch (RuntimeException crash) {
            log.severe("Crash: ledger committed but event NEVER published -> lost event, "
                    + "statements/notifications missing. Kafka txn could not help (DB is outside it).");
        }

        log.info("=== Transactional outbox: atomic ledger + outbox, relay publishes ===");
        Database db2 = new Database();
        KafkaBroker broker2 = new KafkaBroker();
        TransferService service = new TransferService(db2);
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000")); // one txn, both rows
        log.warning("Simulate relay crash BEFORE marking published...");
        OutboxRelay relay = new OutboxRelay(db2, broker2);
        relay.publishPending(log);   // publishes, then 'crash' before mark (simulated inside)
        log.info("Relay restarts and re-publishes unmarked rows (at-least-once)");
        relay.publishPending(log);   // republishes same event

        DedupConsumer consumer = new DedupConsumer();
        int applied = 0;
        for (String payload : broker2.readAll()) applied += consumer.apply(payload, log);
        log.info("Events published=" + broker2.readAll().size()
                + " (duplicate due to relay retry), applied exactly once=" + applied);
    }
}

