class Database {
    final List<String> ledger = new ArrayList<>();
    final List<OutboxEvent> outbox = new ArrayList<>();
    private boolean inTxn = false;

    void begin() { inTxn = true; }
    void commit() { inTxn = false; }
    void applyTransfer(String from, String to, BigDecimal amt) {
        ledger.add("DEBIT " + from + " " + amt);
        ledger.add("CREDIT " + to + " " + amt);
    }
    void insertOutbox(OutboxEvent e) { outbox.add(e); }
    List<OutboxEvent> findUnpublished() {
        List<OutboxEvent> r = new ArrayList<>();
        for (OutboxEvent e : outbox) if (!e.published) r.add(e);
        return r;
    }
}

// ─── Would be in OutboxEvent.java in a real project ───
class OutboxEvent {
    final String id; final String aggregateId; final String type; final String payload;
    boolean published = false;
    OutboxEvent(String id, String aggregateId, String type, String payload) {
        this.id = id; this.aggregateId = aggregateId; this.type = type; this.payload = payload;
    }
    String getId() { return id; }
    String getAggregateId() { return aggregateId; }
    String getPayload() { return payload; }
}

// ─── Would be in TransferService.java (demo copy) ───
class TransferService {
    private final Database db;
    TransferService(Database db) { this.db = db; }
    void transfer(String from, String to, BigDecimal amount) {
        db.begin();                                   // ONE local transaction
        db.applyTransfer(from, to, amount);           // ledger rows
        db.insertOutbox(new OutboxEvent(java.util.UUID.randomUUID().toString(),
                from, "TransferCompleted",
                "{\"id\":\"" + from + "-" + to + "\",\"amount\":" + amount + "}"));
        db.commit();                                  // both commit atomically
    }
}

// ─── Would be in OutboxRelay.java (demo copy) ───
class OutboxRelay {
    private final Database db;
    private final KafkaBroker broker;
    private boolean simulateCrashOnce = true;
    OutboxRelay(Database db, KafkaBroker broker) { this.db = db; this.broker = broker; }

    void publishPending(Logger log) {
        for (OutboxEvent e : db.findUnpublished()) {
            broker.publish(e.getPayload());           // at-least-once
            if (simulateCrashOnce) {
                simulateCrashOnce = false;
                log.severe("Relay crashed AFTER publish, BEFORE markPublished (row stays unmarked)");
                return;                               // do not mark -> will republish
            }
            e.published = true;                        // mark published
            log.info("Relay marked event " + e.getId() + " as published");
        }
    }
}

// ─── Would be in KafkaBroker.java in a real project ───
class KafkaBroker {
    private final List<String> log = new ArrayList<>();
    void publish(String payload) { log.add(payload); }
    List<String> readAll() { return log; }
}

// ─── Would be in DedupConsumer.java in a real project ───
class DedupConsumer {
    private final Set<String> seen = new HashSet<>();
    int apply(String payload, Logger log) {
        String id = payload.replaceAll(".*\"id\":\"([^\"]+)\".*", "$1");
        if (!seen.add(id)) { log.warning("Duplicate event " + id + " skipped"); return 0; }
        log.info("Applied event " + id + " (update statement, send notification)");
        return 1;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
